🐛 Describe the bug
The pipeline interface produces error when initializing module on meta device. If I initialize the module on cuda, everything is fine. It seems that the pipeline captures the input tensor dtype as meta and report error when I pass a cuda tensor to the pipeline during runtime. However, if I change the mb_args to cuda tensor, it complains that the graph cannot be captured as graph breaks exist. How can I use this pipeline interface correctly with very large model?
Mini-repro:
import torch
import torch.nn as nn
import torch.distributed as dist
from torch.distributed.pipelining import pipeline, SplitPoint, ScheduleGPipe

from functools import cached_property


class MyModule(nn.Module):
    def __init__(self, hidden_size: int, num_layers: int):
        super().__init__()
        self.layers = nn.ModuleList([
            nn.Linear(hidden_size, hidden_size) for _ in range(num_layers)
        ])

    def forward(self, x):
        for layer in self.layers:
            x = layer(x)
        return x


class PlayWithPP:
    hidden_size: int = 1024
    num_layers: int = 32

    def run(self):
        num_mb = 4
        batch_size = 32
        x = torch.randn(batch_size, self.hidden_size, device=self.device)
        y = torch.randn(batch_size, self.hidden_size, device=self.device)
        stage, module = self.build_stage()
        schedule = ScheduleGPipe(
            stage,
            n_microbatches=num_mb,
            loss_fn=lambda x, y: (x - y).square().sum(),
        )
        if self.rank == 0:
            schedule.step(x)
        else:
            losses = []
            output = schedule.step(target=y, losses=losses)
            print(output)
            print(losses)

    @cached_property
    def device(self):
        return torch.device(f"cuda:{self.rank}")

    @cached_property
    def rank(self):
        return dist.get_rank()

    @cached_property
    def pp_size(self):
        return dist.get_world_size()

    def build_stage(self):
        with torch.device("meta"):  # OK if changed to self.device
            module = MyModule(self.hidden_size, self.num_layers)
            num_layers_per_pp_rank = self.num_layers // self.pp_size
            pipe = pipeline(
                module,
                mb_args=(torch.ones(8, self.hidden_size),),
                split_spec={
                    f"layers.{i}": SplitPoint.BEGINNING
                    for i in range(
                        num_layers_per_pp_rank,
                        self.num_layers,
                        num_layers_per_pp_rank
                    )
                }
            )
        stage = pipe.build_stage(self.rank, self.device, self.device_mesh.get_group())
        return stage, module

    @cached_property
    def device_mesh(self):
        from torch.distributed.device_mesh import init_device_mesh
        return init_device_mesh("cuda", (dist.get_world_size(),))

if __name__ == "__main__":
    dist.init_process_group(backend="nccl")
    torch.cuda.set_device(dist.get_rank())
    PlayWithPP().run()
    dist.destroy_process_group()
Versions
Torch==2.6.0

Hi,
I was trying to use the L-BFGS to familiarize a bit. My goal would be to use it in a bigger code base.
Specifically I have a simple cost function $f(x_1,...,x_n) = x_1^2 + ... + x_n^2$ which I am trying to optimize.
The code is here:
#include <torch/torch.h>

#include <fstream>
#include <iostream>

// Model: Sum of squares function with learnable parameters
struct Model : torch::nn::Module {
  torch::Tensor param;

  Model(int n) { param = register_parameter("param", torch::rand({n})); }

  torch::Tensor forward() { return torch::sum(torch::pow(param, 2)); }
};

std::tuple<float, size_t> queryLearningRate() {
  std::cout << "Please insert your learning rate as fp number: ";
  float learning_rate;
  std::cin >> learning_rate;

  std::cout << "Please insert the number of epochs: ";
  size_t epoch;
  std::cin >> epoch;

  return {learning_rate, epoch};
}

int main() {
  const int dim = 10;  // Number of parameters

  auto [learning_rate, num_epochs] = queryLearningRate();

  auto model = std::make_shared<Model>(dim);

  // Configure LBFGS optimizer
  torch::optim::LBFGSOptions options(learning_rate);
  options.max_iter(20);             // Number of iterations per .step()
  options.tolerance_grad(1e-10);    // Gradient threshold
  options.tolerance_change(1e-12);  // Function value threshold
  options.history_size(100);  // Optional: more memory for curvature approx
  torch::optim::LBFGS optimizer(model->parameters(), options);

  std::ofstream log_file("lbfgs_loss_log.csv");
  log_file << "epoch,loss\n";

  torch::Tensor loss;

  for (int epoch = 0; epoch < num_epochs; ++epoch) {
    optimizer.zero_grad();

    auto closure = [&]() -> torch::Tensor {
      loss = model->forward();  // scalar loss
      loss.backward();
      return loss;
    };

    optimizer.step(closure);

    std::cout << "Epoch " << epoch << ", Loss: " << loss.item<float>() << "\n";
    log_file << epoch << "," << loss.item<float>() << "\n";
  }

  log_file.close();

  std::cout << "Training complete.\n";
  std::cout << "Final params: " << model->param << "\n";

  return 0;
}

If you run this code and give l_r = 1 and num_epocs = 1000 for example you will see the loss increasing till it gets a NaN. If instead you give l_r < 1 and num_epocs = 1000 the loss won't change at all.
