Run following
import torch

def f(x):
    var, mean = torch.var_mean(x, dim=2, keepdim = True)
    return x / var

if __name__ == "__main__":
    add_1 = torch.rand(1, 256, 1024, dtype=torch.float32, device='mps')

    with torch.no_grad():
        rc = f(add_1)
        rc_c = torch.compile(f)(add_1)
    print((rc - rc_c).abs().max())
Difference should be zero but it isn't, and problem is indeed in the generated code, which looks as follows:
    #include <c10/metal/utils.h>
