        auto r0_index = thread_pos.y;
        int x0 = xindex;
        threadgroup float3 tmp_acc_0[1024];
        tmp_acc_0[r0_index * 1] = 0.0;
        for(auto r0_1_cnt = 0; r0_1_cnt < 1; ++r0_1_cnt) {
            int r0_1 = 1 * r0_index + r0_1_cnt;
            auto tmp0 = in_ptr0[r0_1 + 1024*x0];
